(() => {
  const Z=window.Zucco,{state,platform:P,ui:U,ROUTES:R,escape:E,icon:I,avatar:A,badge:B,btn:BT,money:M}=Z;
  const marketCards=()=>P.market.filter(m=>U.match('market',m.name,m.description)).map(m=>`<article class="panel"><div class="market-visual">${I(m.icon)}${B(m.stock?m.stock+' in stock':'Out of stock',m.stock?'success':'danger')}</div><div class="market-item-body"><h2>${E(m.name)}</h2><p>${E(m.description)}</p><div class="market-footer"><span class="market-price mono">${I('coin')}${m.price} <span class="caption">Coins</span></span><button type="button" class="btn small" data-action="ext-redeem:${m.id}" ${m.stock<=0?'disabled':''}>Redeem reward${I('chevron')}</button></div></div></article>`).join('');
  Z.listRenderers.market=marketCards;
  Z.renderers[R.MARKET]=()=>Z.heading('Reward market','Turn everyday progress into something students can look forward to.',BT('Add reward','ext-new-reward','plus','primary'))+
    U.metrics([['Available rewards',P.market.filter(m=>m.stock>0).length,'Ready to redeem','coin'],['Items in stock',P.market.reduce((a,m)=>a+m.stock,0),'Across the reward catalog','group'],['Pending handovers',P.orders.filter(o=>o.status==='Pending').length,'Prepare these rewards for collection','clock'],['Coins redeemed',P.orders.reduce((a,o)=>a+o.price,0),'Across recorded market orders','coins']])+
    U.tabs([['catalog','Reward catalog',P.market.length],['orders','Student orders',P.orders.length]],P.marketTab,'ext-market-tab')+
    (P.marketTab==='catalog'?U.toolbar('market','Search rewards…')+`<div class="grid-three" id="market-rows">${marketCards()}</div>`:U.table([['Order',13],['Student',25],['Reward',28],['Coins',12],['Status',12],['Action',15]],P.orders.map(o=>`<tr><td class="mono caption">${o.id}</td><td>${E(o.student)}</td><td>${E(o.item)}</td><td><span class="market-price" style="font-size:12px">${I('coin')}${o.price}</span></td><td>${U.status(o.status)}</td><td>${o.status==='Pending'?BT('Mark delivered','ext-deliver:'+o.id,'check','small'):B('Collected','success')}</td></tr>`).join('')));
  const coinRows=()=>P.coinLedger.filter(t=>U.match('coins',t.name,t.reason)).map(t=>`<tr><td><div class="row gap-12">${A(t.name)}<span class="table-primary">${E(t.name)}</span></div></td><td>${E(t.reason)}</td><td><span class="coin-entry mono ${t.amount>0?'text-success':'text-warning'}">${I(t.amount>0?'plus':'coin')}${t.amount>0?'+':'−'}${Math.abs(t.amount)}</span></td><td class="mono">${t.balance} Coins</td><td class="caption">${t.time}</td><td>${B(t.amount>0?'Awarded':'Redeemed',t.amount>0?'success':'warning')}</td></tr>`).join('');
  Z.listRenderers.coins=coinRows;
  Z.renderers[R.COINS]=()=>Z.heading('Coin activity','Recognize effort and keep every reward transparent.',BT('Reward market','go:'+R.MARKET,'coin')+BT('Award coins','ext-award-coins','plus','primary'))+
    U.metrics([['Student coin balance',P.students.reduce((a,s)=>a+Z.studentCoins(s),0),'Coins currently held by students','coins'],['Coins awarded',P.coinLedger.filter(t=>t.amount>0).reduce((a,t)=>a+t.amount,0),'In the current activity sample','plus','success'],['Coins redeemed',-P.coinLedger.filter(t=>t.amount<0).reduce((a,t)=>a+t.amount,0),'Rewards collected or reserved','coin'],['Recent transactions',P.coinLedger.length,'Awards and market redemptions','receipt']])+
    U.toolbar('coins','Search student or coin reason…')+U.table([['Student',26],['Reason',26],['Change',12],['Balance after',14],['Date & time',16],['Type',12]],coinRows(),'coins','<span>Coin transactions show the student balance after each change.</span>')+
    `<div class="equal-panels" style="margin-top:20px">${U.panel('Make recognition part of the lesson',`<p class="caption">Use quick +1 and +5 coin rewards while marking attendance. Reward effort, participation, and progress.</p><div style="height:14px"></div>${BT('Open coin journal','go:'+R.ATTENDANCE,'book','small')}`)}${U.panel('A clear history for every student',`<p class="caption">Every award and redemption has a reason and a resulting balance. Review a student’s profile before issuing a reward.</p><div style="height:14px"></div>${BT('Find a student','go:'+R.STUDENTS,'users','small')}`)}</div>`;
  const smsRows=()=>P.sms.filter(s=>U.match('sms',s.name,s.audience,s.type,s.status)).map(s=>`<tr><td><span class="table-primary">${E(s.name)}</span><p class="table-secondary mono">${s.id}</p></td><td>${E(s.audience)}</td><td>${E(s.type)}</td><td>${U.status(s.status)}</td><td class="caption">${s.time}</td><td>${BT('Preview','ext-sms-preview:'+s.id,'chevron','small ghost')}</td></tr>`).join('');
  Z.listRenderers.sms=smsRows;
  Z.renderers[R.SMS]=()=>Z.heading('SMS center','The right message, at the right moment in the learning journey.',BT('Compose SMS','ext-new-sms','plus','primary'))+
    U.metrics([['Message batches',P.sms.length,'Current communication history','message'],['Provider accepted',P.sms.filter(s=>s.status==='Accepted').length,'Accepted for processing','checkCircle','success'],['Pending / unknown',P.sms.filter(s=>['Pending','Unknown'].includes(s.status)).length,'Check status before sending again','clock'],['Failed',P.sms.filter(s=>s.status==='Failed').length,'Review the provider response','alert','danger']])+
    U.tabs([['history','Message history',P.sms.length],['templates','Message templates',P.templates.length]],P.smsTab,'ext-sms-tab')+
    (P.smsTab==='history'?U.toolbar('sms','Search message, audience, or status…')+U.table([['Message / reference',28],['Audience',15],['Type',19],['Status',12],['Created',17],['',9]],smsRows(),'sms','<span>Provider acceptance does not confirm delivery to the recipient.</span>'):`<div class="grid-three">${P.templates.map((t,i)=>`<article class="panel template-card"><div class="row between"><h2>${E(t.name)}</h2>${I('message')}</div><div class="template-preview">${E(t.body)}</div><div class="row between"><span class="tiny">Personalized student fields</span>${BT('Use template','ext-use-template:'+i,'chevron','small')}</div></article>`).join('')}</div>`)+
    `<p class="sms-notice">${I('alert')}Pending or unknown requests should be checked before retrying, to avoid duplicate messages.</p>`;
})();
